"""Render the human-readable News Ontology from its Python data contract."""

from pathlib import Path

from . import news, primary
from .divergence import gap_directions

GENERATED_PATH = Path(__file__).resolve().parents[3] / "news-ontology.md"


def render_news_ontology() -> str:
    lines = [
        "<!-- Generated by `uv run python -m knowledge_map.ontology.render`; do not edit. -->",
        "# News Ontology", "",
        "The closed set of graph structures the news pipeline can produce. It is a subset",
        "of the primary ontology plus the declared shortcuts below.", "",
        "## Labels and properties", "",
        "| Label | Property names | Sub-labels |", "| --- | --- | --- |",
    ]
    for label in sorted(news.LABELS):
        properties = ", ".join(f"`{item}`" for item in sorted(news.PROPERTIES[label])) or "—"
        sub_labels = ", ".join(f"`{item}`" for item in sorted(news.SUB_LABELS.get(label, ()))) or "—"
        lines.append(f"| `{label}` | {properties} | {sub_labels} |")

    lines.extend(
        [
            "", "## Relationships", "",
            "A relationship asserts that a claim exists and what identifies it — nothing",
            "more. The properties it declares, and only those, are its **Claim Key**: they",
            "are normalized and form the edge's merge key, because the relationship means",
            "something different at a different value — two articles naming different",
            "amounts assert different things and get separate edges. Anything else an",
            "article said about the relationship stays in the `Chunk` the edge points back",
            "to. A Claim Key property is not required of the extractor: an edge that",
            "arrives without one is written and carries `needs_review`.", "",
            "| Type | Sources | Targets | Claim Key |",
            "| --- | --- | --- | --- |",
        ]
    )
    for relationship_type, shape in sorted(news.RELATIONSHIPS.items()):
        sources = " / ".join(f"`{item}`" for item in sorted(shape.source_labels))
        targets = " / ".join(f"`{item}`" for item in sorted(shape.target_labels))
        claim_key = " / ".join(
            f"`{item}`" for item in sorted(news.claim_key_properties(relationship_type))
        ) or "—"
        lines.append(f"| `{relationship_type}` | {sources} | {targets} | {claim_key} |")

    lines.extend(
        [
            "", "## Shortcuts", "",
            "Paths the news write path flattens into one edge, because prose names the",
            "endpoints but not what sits between them. Each rule holds the path it",
            "replaced, so a shortcut edge can be expanded back out from its type alone.",
            "The edge itself records nothing about the collapse: the rule below names the",
            "label to reinsert, and a copy on every edge would only go stale.", "",
        ]
    )
    for shortcut in news.SHORTCUTS:
        path = " → ".join(
            f"`{source}` -`{relationship}`→ `{target}`"
            for source, relationship, target in shortcut.path
        )
        lines.append(
            f"- {path} ⇒ `{shortcut.source_label}` -`{shortcut.relationship_type}`→ "
            f"`{shortcut.target_label}` (`skips`: `{shortcut.skips}`)"
        )

    lines.extend(
        [
            "", "## Divergences from the primary ontology", "",
            "Where the two ontologies part: a property the write path stamps that the",
            "primary ontology does not declare, or one the primary ontology declares that",
            "news cannot supply. Either way it marks something nothing we hold can settle.",
            "Unlike a shortcut, a divergence is not reversible from our own record: closing",
            "one needs an authoritative source.", "",
            "An edge's evidence is not a divergence: the `Chunk` it was read from is",
            "recorded in `chunks`, which the primary ontology has no need of because a",
            "record does not cite a passage. Nor is its collapse, which the shortcut holds.", "",
            "The gap column is derived, not declared: a property the primary ontology",
            "declares is one news drops, and one it does not declare is one the write",
            "path stamps. Nothing records the direction twice.", "",
            "| Property | Applies to | Gap | Why it diverges |",
            "| --- | --- | --- | --- |",
        ]
    )
    relationship_properties = {
        relationship_type: shape.property_names
        for relationship_type, shape in primary.RELATIONSHIPS.items()
    }
    for divergences, primary_properties in (
        (news.NODE_DIVERGENCES, primary.PROPERTIES),
        (news.RELATIONSHIP_DIVERGENCES, relationship_properties),
    ):
        for divergence in divergences:
            applies_to = " / ".join(f"`{item}`" for item in sorted(divergence.applies_to))
            gap = ", ".join(gap_directions(divergence, primary_properties))
            lines.append(
                f"| `{divergence.property_name}` | {applies_to} | {gap} | "
                f"{divergence.reason} |"
            )

    shortcut_types = {shortcut.relationship_type for shortcut in news.SHORTCUTS}
    excluded_relationships = sorted(
        primary.RELATIONSHIPS.keys() - news.RELATIONSHIPS.keys() - shortcut_types
    )
    lines.extend(
        [
            "", "## Primary ontology concepts outside news scope", "",
            "Labels: "
            + ", ".join(f"`{label}`" for label in sorted(primary.LABELS - news.LABELS))
            + ".", "",
            "Relationships: "
            + ", ".join(f"`{item}`" for item in excluded_relationships)
            + ".",
        ]
    )

    lines.extend(["", "## Policy Areas", "", "| ID | Name |", "| --- | --- |"])
    lines.extend(f"| `{area.id}` | {area.name} |" for area in news.POLICY_AREAS)
    return "\n".join(lines) + "\n"


def main() -> None:
    GENERATED_PATH.write_text(render_news_ontology())


if __name__ == "__main__":
    main()
